"""Локальная галерея PNG-кадров; браузеру не нужны сеть или сервер."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
NAMES={'02':'Щит дозора','05':'Тяжёлый страж','11':'Красный бастион','12':'Синий щитоносец','17':'Седой бастион','18':'Лазурный мечник'}

def main():
    data=[]
    for id,name in NAMES.items():
        clips=[]
        for kind in ('idle','death','ability'):
            for provider in ('pixellab','local'):
                for n in (range(1,4) if provider=='pixellab' else [1]):
                    folder=ROOT/'pixellab'/f'{id}-{kind}-{n}' if provider=='pixellab' else ROOT/'local'/id/kind
                    path=folder/'clip.json'
                    if path.exists():
                        meta=json.loads(path.read_text(encoding='utf-8'))
                        clips.append({'kind':kind,'provider':provider,'variant':n,'path':folder.relative_to(ROOT).as_posix(),**{k:meta.get(k) for k in ('actual_frames','durations_ms','loop','ability_title','edge_frames','margin_violation_frames')}})
        data.append({'id':id,'name':name,'clips':clips})
    template='''<!doctype html><html lang="ru"><meta charset="utf-8"><title>Шесть воинов — анимации</title><style>
*{box-sizing:border-box}body{margin:0;background:#101723;color:#e8eef5;font:16px system-ui}header{padding:24px 32px;background:#1a2434;position:sticky;top:0;z-index:2}h1{font-size:25px;margin:0 0 10px}p{color:#b5c3d5;line-height:1.5}button,select{background:#2b3c54;border:1px solid #546a87;border-radius:7px;color:white;padding:8px 13px;margin:3px;cursor:pointer}button.active{background:#795831;border-color:#efba66}main{max-width:1500px;margin:auto;padding:24px}.models{display:flex;align-items:center;gap:24px}.models img{width:220px;height:220px;object-fit:contain;background:#1b2739}.models a{color:#eabe75}.row{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:14px}article{background:#1b2739;border:1px solid #34465e;border-radius:10px;overflow:hidden;text-align:center}article h3{font-size:15px}.stage{height:280px;display:flex;align-items:center;justify-content:center;background:var(--bg,#182131)}canvas{width:256px;height:auto;max-width:100%;image-rendering:pixelated}body.game canvas{width:102.4px;height:102.4px}body.zoom canvas{width:384px;height:auto}body.zoom .row{grid-template-columns:repeat(2,minmax(150px,1fr))}body.zoom .stage{height:400px}a{color:#eabe75}.muted{font-size:13px;color:#9fb0c6}.warning{color:#ffb577}input[type=range]{width:90%}@media(max-width:800px){.row{grid-template-columns:repeat(2,1fr)}body.zoom .row{grid-template-columns:1fr}header{position:static}main{padding:12px}}
</style><header><h1>Шесть воинов · сравнение анимаций</h1><nav id="tabs"></nav><div><button id="play">Пауза</button><button id="restart">Сначала</button><button id="step">+ Кадр</button><select id="scale"><option value="">Масштаб 1×</option><option value="game">Игровой размер (~61 px)</option><option value="zoom">Масштаб 1,5×</option></select><select id="speed"><option value="1">Скорость 1×</option><option value="0.5">0,5×</option><option value="1.5">1,5×</option></select><select id="background"><option value="#182131">Тёмный фон</option><option value="#88939c">Серый фон</option><option value="#ded4b9">Светлый фон</option></select></div></header><main><div id="model"></div><p>Три варианта PixelLab и одна локальная проба на каждый тип. Смерть и способность проигрываются один раз и удерживают последний кадр; «Сначала» повторяет. Локальные пробы — движение вырезанных частей исходника. У PixelLab возврат к исходной позе может отличаться; плавность стыка idle ещё требует выбора и проверки. В игру не подключено.</p><div id="clips"></div></main><script>
const DATA=__DATA__;let current='02',playing=true,speed=1,last=0,players=[];const labels={idle:'Ожидание',death:'Смерть',ability:'Способность'};
function render(){players=[];document.querySelector('#tabs').innerHTML=DATA.map(m=>`<button class="${m.id===current?'active':''}" data-id="${m.id}">${m.id} · ${m.name}</button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{current=b.dataset.id;render()});const m=DATA.find(x=>x.id===current);document.querySelector('#model').innerHTML=`<div class="models"><img src="models/warrior-${m.id}/input-256.png"><div><h2>${m.id} · ${m.name}</h2><p>Прозрачная модель · холст 256×256 · опора (128,200)</p><a href="models/warrior-${m.id}/source-full.png" target="_blank">Открыть полноразмерную модель</a></div></div>`;let html='';for(const kind of ['idle','death','ability']){html+=`<h2>${labels[kind]}</h2><div class="row">`;for(const provider of ['pixellab','local'])for(const n of provider==='pixellab'?[1,2,3]:[1]){const c=m.clips.find(c=>c.kind===kind&&c.provider===provider&&c.variant===n);if(!c){html+=`<article><h3>${provider} ${n}</h3><p>Ожидается результат</p></article>`;continue}const index=players.length;players.push({c,frame:0,time:0,img:new Image(),loaded:false});html+=`<article><h3>${provider==='local'?'Локальная проба':'PixelLab · '+n}</h3><div class="stage"><canvas width="256" height="256" data-player="${index}"></canvas></div><input type="range" min="0" max="${c.actual_frames-1}" value="0" data-slider="${index}"><p class="muted">${c.actual_frames} кадров · ${kind==='idle'?'цикл':'одно исполнение'}</p>${(c.edge_frames?.length||c.margin_violation_frames?.length)?'<p class="warning">Есть пиксели в зоне отступа у края</p>':''}<p><a href="${c.path}/preview.gif" target="_blank">GIF</a> · <a href="${c.path}/spritesheet.png" target="_blank">PNG-лист</a></p></article>`}html+='</div>'}document.querySelector('#clips').innerHTML=html;players.forEach((p,i)=>{p.canvas=document.querySelector(`[data-player="${i}"]`);p.slider=document.querySelector(`[data-slider="${i}"]`);p.slider.oninput=()=>{playing=false;document.querySelector('#play').textContent='Играть';p.frame=+p.slider.value;p.time=0;draw(p)};p.img.onload=()=>{p.loaded=true;draw(p)};p.img.src=p.c.path+'/spritesheet.png'});last=0}
function draw(p){if(!p.loaded)return;const ctx=p.canvas.getContext('2d');ctx.clearRect(0,0,256,256);ctx.drawImage(p.img,(p.frame%8)*256,Math.floor(p.frame/8)*256,256,256,0,0,256,256);p.slider.value=p.frame}
function tick(t){if(!last)last=t;let dt=Math.min(100,t-last);last=t;if(playing)players.forEach(p=>{if(!p.loaded)return;p.time+=dt*speed;let duration=p.c.durations_ms?.[p.frame]||90;while(p.time>=duration){p.time-=duration;if(p.frame<p.c.actual_frames-1)p.frame++;else if(p.c.kind==='idle')p.frame=0;else{p.time=0;break}duration=p.c.durations_ms?.[p.frame]||90}draw(p)});requestAnimationFrame(tick)}
document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Пауза':'Играть'};document.querySelector('#restart').onclick=()=>{players.forEach(p=>{p.frame=0;p.time=0;draw(p)});playing=true;document.querySelector('#play').textContent='Пауза'};document.querySelector('#step').onclick=()=>{playing=false;document.querySelector('#play').textContent='Играть';players.forEach(p=>{p.frame=Math.min(p.frame+1,p.c.actual_frames-1);draw(p)})};document.querySelector('#scale').onchange=e=>document.body.className=e.target.value;document.querySelector('#speed').onchange=e=>speed=+e.target.value;document.querySelector('#background').onchange=e=>document.documentElement.style.setProperty('--bg',e.target.value);render();requestAnimationFrame(tick);
</script></html>'''
    (ROOT/'gallery.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf-8')
    print('Gallery clips',sum(len(m['clips']) for m in data))
if __name__=='__main__':main()
